#[storage]
pub struct Checkpoint<S: Size> {
    /// The key of the checkpoint. Used as a sorting key.
    pub(crate) key: S::KeyStorage,
    /// The value corresponding to the key.
    pub(crate) value: S::ValueStorage,
}

impl<S: Size> Trace<S> {
    /// Pushes a (`key`, `value`) pair into a `Trace` so that it is
    /// stored as the checkpoint.
    ///
    /// Returns the previous value and the new value as an ordered pair.
    ///
    /// IMPORTANT: Never accept `key` as user input, since an arbitrary
    /// `U96::MAX` key set will disable the library.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the checkpoint's state.
    /// * `key` - Latest checkpoint key to insert.
    /// * `value` - Checkpoint value corresponding to `key`.
    ///
    /// # Errors
    ///
    /// * [`Error::CheckpointUnorderedInsertion`] - If the `key` is lower than
    ///   previously pushed checkpoint's key (necessary to maintain sorted
    ///   order).
    pub fn push(
        &mut self,
        key: S::Key,
        value: S::Value,
    ) -> Result<(S::Value, S::Value), Error> {
        self._insert(key, value)
    }

    /// Returns the value in the first (oldest) checkpoint with key greater or
    /// equal than the search key, or `S::Value::ZERO` if there is none.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `key` - Checkpoint's key to lookup.
    pub fn lower_lookup(&self, key: S::Key) -> S::Value {
        let len = self.length();
        let pos = self._lower_binary_lookup(key, U256::ZERO, len);
        if pos == len {
            S::Value::ZERO
        } else {
            self._index(pos).value.get()
        }
    /// recipient must implement [`IErc721Receiver::on_erc721_received`] and
    /// return the acceptance magic value to accept the transfer.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `operator` - Account to add to the set of authorized operators.
    /// * `from` - Account of the sender.
    /// * `to` - Account of the recipient.
    /// * `token_id` - Token id as a number.
    /// * `data` - Additional data with no specified format, sent in call to
    ///   `to`.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidReceiver`] - If
    ///   [`IErc721Receiver::on_erc721_received`] hasn't returned its interface
    ///   id or returned an error.
    /// * [`Error::InvalidReceiverWithReason`] - If
    ///   [`IErc721Receiver::on_erc721_received`] reverted with revert data.
    pub fn _check_on_erc721_received(
        &mut self,
        operator: Address,
        from: Address,
        to: Address,
        token_id: U256,
        data: &Bytes,
    ) -> Result<(), Error> {
        if self.vm().code_size(to) == 0 {
            return Ok(());
        }

        let receiver = IErc721ReceiverInterface::new(to);
        let call = Call::new_mutating(self);
        let result = receiver.on_erc_721_received(
            self.vm(),
            call,
            operator,
            from,
            token_id,
            data.to_vec().into(),
        );

        let id = match result {
            Ok(id) => id,
            Err(e) => {
                if let stylus_sdk::stylus_core::calls::errors::Error::Revert(
                    ref reason,
                ) = e
                {
                    if !reason.is_empty() {
                        return Err(Error::InvalidReceiverWithReason(
                            InvalidReceiverWithReason {
                                reason: String::from_utf8_lossy(reason)
                                    .to_string(),
                            },
                        ));
                    }
                }

                // Non-IERC721Receiver implementer.
                return Err(ERC721InvalidReceiver { receiver: to }.into());
            }
        };

        // Token rejected.
        if id != RECEIVER_FN_SELECTOR {
            return Err(ERC721InvalidReceiver { receiver: to }.into());
        }

        Ok(())
    }
}
