    fn from(err: Error) -> Vec<u8> {
        match err {
            Error::Revert(data) => data,
            #[allow(unused)]
            Error::AbiDecodingFailed(err) => Panic::from(PanicKind::Generic).abi_encode(),
        }
    }
}

