   34|       |/// Adds an `interface_id` associated function to your trait by XOR-ing all
   35|       |/// method selectors together, following the ERC-165 standard.
   36|       |///
   37|       |/// ## Method naming
   38|       |///
   39|       |/// By default, Rust method names are converted to camelCase for Solidity.
   40|       |/// Use `#[selector(name = "...")]` to override the Solidity function name.
   41|       |///
   42|       |/// ## Examples
   43|       |///
   44|       |/// ### Basic usage
   45|       |///
   46|       |/// ```rust,ignore
   47|       |/// #[interface_id]
   48|       |/// pub trait IErc721 {
   49|       |///     fn balance_of(&self, owner: Address) -> Result<U256, Vec<u8>>;
   50|       |///     fn owner_of(&self, token_id: U256) -> Result<Address, Vec<u8>>;
   51|       |///
   52|       |///     // Function overloading: different Rust names, same Solidity name
   53|       |///     fn safe_transfer_from(
   54|       |///         &mut self,
   55|       |///         from: Address,
   56|       |///         to: Address,
   57|       |///         token_id: U256,
   58|       |///     ) -> Result<(), Vec<u8>>;
   59|       |///
   60|       |///     #[selector(name = "safeTransferFrom")]
   61|       |///     fn safe_transfer_from_with_data(
   62|       |///         &mut self,
   63|       |///         from: Address,
   64|       |///         to: Address,
   65|       |///         token_id: U256,
   66|       |///         data: Bytes,
   67|       |///     ) -> Result<(), Vec<u8>>;
   68|       |/// }
   69|       |///
   70|       |/// // Now you can use the computed interface ID:
   71|       |/// impl IErc165 for Erc721 {
   72|       |///     fn supports_interface(&self, interface_id: B32) -> bool {
   73|       |///         <Self as IErc721>::interface_id() == interface_id
   74|       |///             || <Self as IErc165>::interface_id() == interface_id
   75|       |///     }
   76|       |/// }
   77|       |/// ```
   78|       |///
   79|       |/// ### Selector collision error
   80|       |///
   81|       |/// The macro rejects duplicate canonical signatures and distinct signatures
   82|       |/// with the same four-byte selector at compile time:
   83|       |///
   84|       |/// ```compile_fail
   85|       |/// #[interface_id]
   86|       |/// trait BadTrait {
   87|       |///     fn transfer(&self, to: Address, amount: U256);          // transfer(address,uint256)
   88|       |///
   89|       |///     #[selector(name = "transfer")]
   90|       |///     fn send_tokens(&self, recipient: Address, value: U256); // same canonical signature ❌
   91|       |/// }
   92|       |/// ```
   93|       |#[proc_macro_attribute]
   94|    113|pub fn interface_id(attr: TokenStream, input: TokenStream) -> TokenStream {
   95|    113|    interface_id::interface_id(&attr, input)
   96|    113|}

